insert into public.country_occupation_metric_snapshots (profile_key,as_of_date,shortage_component,vacancy_intensity_component,employer_diversity_component,vacancy_trend_component,entry_level_component,salary_component,growth_component,visa_component,entry_burden_component,opportunity_score,score_methodology_version,score_status,score_evidence,source_checked_at) values
('SG:civil-engineer','2026-08-11',0,0,0,0,10,0,0,0,3,13,'career-opportunity-sg-v1','provisional',jsonb_build_object('classification_scope','SSOC 2024 maps the canonical role directly to 21421 Civil engineer; 21422 Building construction engineer remains separate.','entry_level_basis','Professional civil-engineering degrees provide direct preparation and four approved Singapore programmes are retained as direct study pathways.','qualification_note','The broad employee occupation is not universally limited to individually registered Professional Engineers. Under the Professional Engineers Act, prescribed professional engineering work in civil engineering must be performed by a registered PE with a practising certificate or by a person working under such a PE''s direction or supervision.','market_scope','No exact shortage, vacancy, earnings or growth series is scored in the foundation phase.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11'),
('SG:mechanical-engineer','2026-08-11',0,0,0,0,10,0,0,0,3,13,'career-opportunity-sg-v1','provisional',jsonb_build_object('classification_scope','SSOC 2024 maps the canonical general role directly to 21441 Mechanical engineer, distinct from industrial machinery/tools, HVAC and transport engineering occupations.','entry_level_basis','Professional mechanical-engineering degrees provide direct preparation and four approved programmes are direct study pathways.','qualification_note','Mechanical engineering is a prescribed branch under the Professional Engineers Act for regulated professional engineering work, but employees may work under the direction or supervision of a registered PE; therefore the broad occupation is not treated as universally requiring each worker to hold PE registration.','market_scope','No market components are inferred from registration or programme availability.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11'),
('SG:electrical-engineer','2026-08-11',0,0,0,0,10,0,0,0,3,13,'career-opportunity-sg-v1','provisional',jsonb_build_object('classification_scope','SSOC 2024 maps the canonical general role directly to 21511 Electrical engineer; power generation/distribution engineer 21512 and lift engineer 21513 remain separate occupations.','entry_level_basis','Electrical and electronic engineering study provides direct preparation; five approved programmes are retained as direct study pathways.','qualification_note','Electrical engineering is a prescribed PE branch for regulated professional engineering work, while Energy Market Authority Licensed Electrical Worker requirements apply to defined electrical-work scopes. These rules do not mean every person employed under SSOC 21511 must personally hold both registrations.','market_scope','No demand or earnings credit is inferred from regulatory status.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11'),
('SG:manufacturing-engineer','2026-08-11',0,0,0,0,10,0,0,0,5,15,'career-opportunity-sg-v1','provisional',jsonb_build_object('classification_scope','SSOC 2024 directly identifies 21411 Manufacturing engineer within Industrial and Production Engineers. Production, automation, quality and process engineering remain separate five-digit occupations.','entry_level_basis','Manufacturing, mechanical, materials and industrial-systems engineering study provide relevant preparation; five approved programmes are related academic pathways.','qualification_note','Manufacturing engineering is not itself one of the prescribed PE registration branches. Particular work may cross into regulated mechanical, electrical, chemical or civil professional engineering scopes, but that does not create universal personal registration for all manufacturing engineers.','market_scope','No exact current labour-market series has yet been normalised into SG v1.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11'),
('SG:industrial-engineer','2026-08-11',0,0,0,0,10,0,0,0,5,15,'career-opportunity-sg-v1','provisional',jsonb_build_object('classification_scope','SSOC 2024 has the 2141 Industrial and Production Engineers unit group but no single five-digit occupation titled Industrial engineer. CampCareer preserves representative manufacturing 21411, production 21412, quality 21414 and process 21415 scopes rather than inventing an exact code.','entry_level_basis','Industrial and systems engineering, engineering systems and operations-oriented study provide relevant preparation; three approved programmes are related pathways.','qualification_note','Industrial engineering is not a standalone prescribed PE registration branch. Regulated work that substantively falls within civil, electrical, mechanical or chemical professional engineering remains subject to those legal boundaries.','market_scope','The four reference occupations are not merged into a fabricated exact Industrial Engineer market series.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11'),
('SG:chemical-engineer','2026-08-11',0,0,0,0,10,0,0,0,3,13,'career-opportunity-sg-v1','provisional',jsonb_build_object('classification_scope','The primary general chemical-engineering anchor is SSOC 21451 Chemical engineer excluding petroleum and petrochemical. 21452 petroleum and 21453 petrochemical are retained as related classification references, not silently rolled into the primary general code.','entry_level_basis','Chemical and biomolecular engineering degrees provide the core pathway; four approved programmes are related academic pathways because programme completion alone does not confer PE practice rights.','qualification_note','Chemical engineering is a prescribed branch of professional engineering work. A person independently engaging in prescribed professional engineering work must satisfy the Professional Engineers Act, while employees may perform such work under the direction or supervision of a registered PE with a practising certificate.','market_scope','General and petroleum/petrochemical codes are kept distinct and market components remain unscored.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11'),
('SG:environmental-engineer','2026-08-11',0,0,0,0,10,0,0,0,5,15,'career-opportunity-sg-v1','provisional',jsonb_build_object('classification_scope','SSOC 2024 maps Environmental engineer directly to 21430.','entry_level_basis','Environmental and sustainability engineering study provides direct subject preparation; three approved programmes are related academic pathways under the reviewed staging relationship.','qualification_note','Environmental engineering is not itself listed as a prescribed PE registration branch. Specific designs or professional engineering services may fall within civil, chemical, electrical or mechanical prescribed work and must then comply with the relevant PE requirements.','market_scope','Environmental compliance obligations are not converted into occupation demand evidence.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11'),
('SG:engineering-technician','2026-08-11',0,0,0,0,15,0,0,0,5,20,'career-opportunity-sg-v1','provisional',jsonb_build_object('classification_scope','Engineering Technician is intentionally a multidisciplinary umbrella. SSOC 2024 separates civil 31121, electrical 31131, electronics 31141, mechanical 31151, chemical 31161 and manufacturing 31171 technician occupations.','entry_level_basis','Diploma, polytechnic, technical and applied engineering pathways commonly prepare technicians; the seven reviewed university engineering programmes are kept only as related pathways rather than direct technician credentials.','qualification_note','There is no single universal Engineering Technician registration. Specific electrical, building, lift, safety, site or regulated engineering duties can impose role-specific competency or supervision requirements.','market_scope','Discipline technician codes are not aggregated into one exact salary, vacancy or shortage series in SG v1.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11')
